  parts=[]
  c=m.get('content')
  if c: parts.append(str(c))
  for tc in m.get('tool_calls') or []: parts.append(json.dumps(tc,ensure_ascii=False))
  s=' '.join(parts)
  if pat.search(s): hits.append((i,s[:1600].replace('\n',' ')))
 if hits:
  print('\n###',os.path.basename(p))
  for i,s in hits: print(f'M{i}: {s}')
